        'wind-tunnel-to-road-data' => [
            'title'   => 'ממבחני מנהרת רוח לנתוני דרך אמיתיים: הממצאים המדעיים האחרונים באווירודינמיקת נגררים',
            'excerpt' => 'מדוע הרווח שנמדד במנהרה מתכווץ על הכביש? מחקרים מודרניים סוגרים את הפער בין המעבדה לשטח באמצעות טלמטריה ונתוני נהיגה אמיתיים.',
            'content' => '
                <p>הכלי הקלאסי של הפיתוח האווירודינמי היה מנהרת הרוח; אולם מודלים בקנה מידה מוקטן, זווית רוח קבועה ותנאי קרקע אידאליים מייצגים רק באופן חלקי את מורכבותה של התנועה האמיתית. מגמת המחקר של השנים האחרונות ברורה: השופט הסופי הוא נתוני הדרך האמיתיים.</p>
                <h2>פירמידת האימות</h2>
                <ul>
                    <li><strong>סימולציית CFD:</strong> סינון מהיר וזול של גרסאות תכנון</li>
                    <li><strong>מנהרת רוח:</strong> מדידת התצורות הנבחרות בסביבה מבוקרת</li>
                    <li><strong>מבחני מסלול:</strong> אימות ביניים בפרוטוקולי מהירות קבועה וגלישה חופשית (coast-down)</li>
                    <li><strong>טלמטריית צי:</strong> ההוכחה הסופית באמצעות נתוני דלק ו-GPS בתפעול אמיתי הנמשך חודשים</li>
                </ul>
                <h2>מה למדנו מהשטח</h2>
                <p>מחקרים עדכניים המבוססים על מדידות נהיגה אמיתיות העלו שני ממצאים קריטיים. הראשון: הרווח בכביש נמוך בדרך כלל מערך המנהרה, משום שהתנועה, זווית הרוח ופרופיל המהירות סוטים מהאידאל. השני: תחת רוח צולבת, חלק מהציוד מפגין ביצועים טובים מתחזית המנהרה; חצאית הצד היא הדוגמה הטיפוסית. לכן החלטות רכש אינן צריכות להתבסס על נתון קטלוגי בודד, אלא על נתונים שנמדדו בתנאים הדומים לפרופיל התפעול שלכם.</p>
                <h2>מקורות</h2>
                <ul>
                    <li>Madhusudhanan, A. K., Na, X., Boies, A. &amp; Cebon, D. (2021). Effects of semi-trailer modifications on HGV fuel consumption. <em>Transportation Research Part D: Transport and Environment</em>, 92, 102717. DOI: 10.1016/j.trd.2021.102717</li>
                    <li>Van Raemdonck, G. M. R. &amp; Urila, I. (2019). A Study in Options to Improve Aerodynamic Profile of Heavy-Duty Vehicles in Europe. <em>Sustainability</em>, 11(19), 5519. DOI: 10.3390/su11195519</li>
                </ul>
            ',
        ],

        'tipper-wear-plate-hardox-400-450' => [
            'title'   => 'בחירת לוח שחיקה למרכב נגרר רכינה: Hardox 400 מול 450',
            'excerpt' => 'ההבדל בין שתי דרגות הקשיות הוא 50 ברינל על הנייר; בשטח הוא עצם האיזון בין חיי המרכב, המשקל העצמי ועלות העיבוד.',
            'content' => '
                <p>לוח השחיקה במרכב הרכינה הוא המשטח הנמצא במגע מתמיד עם החומר המובל, והוא הקובע את חייו הכלכליים של המרכב. דרגות הקשיות 400 ו-450 של פלדות עמידות שחיקה הן שתי הבחירות הנפוצות ביותר בתחום זה; וההחלטה הנכונה תלויה באופיו של המטען המובל.</p>
                <h2>אופיין של שתי הדרגות</h2>
                <p>דרגת 400 ברינל מציעה פרופיל מאוזן בין קשיות לחסינות: היא ניתנת לכיפוף, קלה לריתוך, וסיכון הסדיקה שלה בעומסי הלם נמוך. דרגת 450, עם קשיות גבוהה בכעשרה אחוזים, מספקת אורך חיים ארוך משמעותית מול שחיקת החלקה; בתמורה, פעולות העיצוב והקידוח דורשות הקפדה רבה יותר.</p>
                <h2>בחירה לפי סוג המטען</h2>
                <ul>
                    <li><strong>עבודות עפר, אדמה, חול:</strong> דרגת 400 מספיקה בדרך כלל; יתרון החסינות בולט</li>
                    <li><strong>אבן גרוסה, פסולת בניין, קרצוף אספלט:</strong> דרגת 450 יוצרת הבדל באורך החיים בשחיקת החלקה</li>
                    <li><strong>סלעים גדולים והעמסת הלם:</strong> פתרונות משולבים, כגון רצפה בדרגת 450 ודופנות בדרגת 400, מניבים תוצאה מאוזנת</li>
                </ul>
                <p>אין לשכוח את המשוואה הבאה: לוח קשה יותר יכול לשמש דק יותר; חתך דק יותר מפחית את המשקל העצמי ומאפשר להוביל יותר מטען בכל נסיעה. לכן בחירת הלוח אינה שאלה של קטלוג חומרים, אלא חישוב של כלכלת התפעול.</p>
            ',
        ],

        'silo-tipper-wind-resistance' => [
            'title'   => 'כיצד מפחיתים את התנגדות הרוח בנגררי צובר ורכינה?',
            'excerpt' => 'גוף הצובר הגלילי מתחיל ביתרון אווירודינמי; הרכינה — בחיסרון, עם מרכבה הפתוח. בשני הסוגים הרווח מגיע ממשמעת של פרטים.',
            'content' => '
                <p>האווירודינמיקה של נגררים לא-תיבתיים הוזנחה זמן רב; אולם מחקרי שטח מראים שפלח זה מחזיק בנתח משמעותי מסך הקילומטראז׳ של הרכב הכבד, ושפוטנציאל השיפור בו עודנו גדול.</p>
                <h2>סדרי עדיפויות בצובר</h2>
                <p>הגוף הגלילי הוא נקודת פתיחה טובה מבחינת הזרימה; הבעיה היא בתוספות. צינורות הפריקה, הסולמות, פלטפורמת המעבר העליונה וקבוצת השסתומים יוצרים איי ערבולים סביב הגוף הנקי. הטמעת ציוד זה בקו הגוף או כיסויו במכסים, בשילוב עם חצאית צד, מספקת רווח משמעותי.</p>
                <h2>סדרי עדיפויות ברכינה</h2>
                <p>פתח המרכב הפתוח פועל במהירות גבוהה כמו בלם אוויר של ממש. מערכות ברזנט אוטומטיות קריטיות לא רק לבטיחות המטען אלא גם לאווירודינמיקה: ברזנט סגור ומתוח קוטע במידה רבה את הערבולים בתוך המרכב. יישור הדופן הקדמית עם תא הנהג של התומך וסידור תחתית השלדה בחצאיות קצרות הם פריטי הרווח הנותרים.</p>
                <ul>
                    <li>כסו או הטמיעו את כל הציוד הנוסף בכיוון הזרימה</li>
                    <li>שמרו על הברזנט סגור בכל נסיעה, גם בחזרה ריקה</li>
                    <li>חצאיות צד קצרות ועמידות מתאימות לתנאי אתרי בנייה</li>
                    <li>עדכנו את כוונון הספוילר של התומך לפי גובה המרכב</li>
                </ul>
                <h2>מקורות</h2>
                <ul>
                    <li>Durbin, T. D., Johnson, K. C., Jung, H. &amp; Miller, J. W. (2021). Characterizing non-box trailer activity and aerodynamic devices for greenhouse gas emissions reductions. <em>Transportation Research Part D: Transport and Environment</em>, 98, 102763. DOI: 10.1016/j.trd.2021.102763</li>
                </ul>
            ',
        ],

        'lowbed-high-strength-steel' => [
