            'excerpt' => 'יותר מטען באותם ממדים חיצוניים, פלטפורמה נמוכה יותר ואורך חיי עייפות ארוך יותר: פלדה בחוזק גבוה היא המהפכה השקטה של הנדסת הלואו-בד.',
            'content' => '
                <p>בנגרר לואו-בד מתחרים שני ערכים: כושר ההובלה וגובה הטעינה. עם פלדת מבנה קלאסית, שיפור אחד מהם משמעו לרוב ויתור על השני; פלדות בחוזק גבוה ביטלו במידה רבה את הדילמה הזו.</p>
