        'trailer-design-for-electric-trucks' => [
            'title'   => 'תכנון נגררים תואמי גוררים חשמליים: למה יש לשים לב?',
            'excerpt' => 'הנגרר המחובר מאחורי גורר חשמלי אינו רק נושא משא עוד; הוא הופך לשותף ישיר של הטווח, היעילות ותכנון הטעינה.',
            'content' => '
                <p>בגורר חשמלי כל קילוואט-שעה יקר; ברכב שלא ניתן למלא את מכלו תוך דקות, כל התנגדות נוספת הנגרמת על ידי הנגרר נגרעת ישירות מהטווח. לכן מפרט הנגררים של עסקים המתכוננים לצי חשמלי חייב אף הוא להשתנות.</p>
                <h2>שני אויבי הטווח: התנגדות ומשקל</h2>
                <p>התנגדות האוויר היא סעיף ההוצאה המרכזי בצריכת האנרגיה במהירות שיוט; ציוד אווירודינמי כגון חצאיות צד, ניהול רווחים וסידור אחורי הופך קריטי יותר בצירוף החשמלי מאשר בדיזל. צמיגים בעלי התנגדות גלגול נמוכה ויישור סרנים נכון הם חלק מאותו חישוב. כל קילוגרם שנחסך ממשקל הריק נכתב לטובת הטווח או לטובת המטען השימושי; אסטרטגיית חומרים קלים רוכשת ערך מחודש בעידן החשמלי.</p>
                <h2>רשימת בדיקה לתאימות</h2>
