        'what-is-adr-basics' => [
            'title'   => 'מהו ADR? כללי היסוד של הובלת חומרים מסוכנים',
            'excerpt' => 'מדלק ועד חומרים מאכלים, מסגרת ה-ADR הבינלאומית מסדירה את ההובלה הבטוחה של חומרים מסוכנים בכביש; היא נשענת על ארבע רגליים: רכב, ציוד, מסמכים ואדם.',
            'content' => '
                <p>דלק, גז בישול, כימיקלים תעשייתיים ומאות מוצרים נוספים מובלים מדי יום בכביש; השם של המסגרת הבינלאומית המבטיחה שהובלה זו בטוחה הוא ADR. הסכם זה, המסדיר את ההובלה הבינלאומית של חומרים מסוכנים בכביש, אף שמקורו אירופי, מהווה כיום את הבסיס לחקיקה הלאומית בגאוגרפיה רחבה, כולל טורקיה.</p>
                <h2>ההיגיון של המערכת: סווג את הסיכון, התאם את האמצעי</h2>
                <p>בליבת חקיקת ה-ADR עומד הסיווג: כל חומר מסוכן משויך לסוג לפי הסיכון העיקרי שהוא מייצר (נוזל דליק, גז בלחץ, חומר מאכל, רעל וכדומה) ומזוהה במספר חומר. סוג זה קובע בשרשרת את האריזה, המיכל, ציוד הרכב, התיוג ותנאי ההובלה.</p>
                <h2>ארבע הרגליים הבסיסיות</h2>
                <ul>
                    <li><strong>רכב ומיכל:</strong> מיכליות לחומרים מסוכנים מיוצרות בתכנון מאושר, ומוכיחות את התאמתן במוסדות תקופתיים</li>
                    <li><strong>ציוד:</strong> ממטפי אש ועד שלטי אזהרה, ציוד הבטיחות המתאים לסוג המובל נמצא ברכב</li>
                    <li><strong>מסמכים:</strong> תעודת ההובלה, ההוראות בכתב ותעודות אישור הרכב הם תעודת הזהות של הסיוע</li>
                    <li><strong>אדם:</strong> הנהגים מוסמכים בהכשרה מיוחדת; העסקים עובדים עם יועץ בטיחות לחומרים מסוכנים</li>
                </ul>
