            'excerpt' => 'מיכלית חצי מלאה עלולה להיות מסוכנת יותר ממיכלית מלאה: הנוזל בעל פני השטח החופשיים נסחף יחד עם הרכב בפנייה, ומושך כלפי מטה את סף ההתהפכות.',
            'content' => '
                <p>עובדה מנוגדת לאינטואיציה אך מוכרת היטב בשטח: מיכלית מלאה בחלקה עלולה להיות פחות יציבה ממיכלית מלאה לגמרי. הסיבה היא פני השטח החופשיים של הנוזל. במיכל מלא לגמרי הנוזל אינו יכול לנוע ומתנהג כמו מטען מוצק; בדוליות חלקית, לעומת זאת, מסה של מאות ואלפי קילוגרמים נעה בחופשיות בתוך המיכל.</p>
                <h2>המכניקה של הכלכלה</h2>
                <p>כאשר הרכב נכנס לפנייה, הנוזל, מכוח האינרציה, נערם כלפי חוץ; מרכז הכובד נע הן בכיוון הרוחבי והן כלפי מעלה. הרוחב האפקטיבי הקובע את ההתנגדות להתהפכות מצטמצם בכך. המסוכן יותר הוא אפקט העיכוב: גל הנוזל פוגע במיכל זמן קצר לאחר תנועת ההגה. בתמרונים עוקבים כמו החלפת נתיב, אם הגל מסתנכרן עם התנודה של הרכב, כל תנודה גדלה מקודמתה והיציבות שהנהג חש נעלמת בפתאומיות.</p>
                <h2>הגורמים המנהלים את הסיכון</h2>
                <ul>
