                    <li>חתך המיכל: חתכים נמוכים ורחבים מורידים את מרכז הכובד</li>
                    <li>דלגקיר ובחלמות: פירוק תנועת הנוזל שובר את אנרגיית הכלכלה</li>
                    <li>משמעת מהירות ותמרון: כניסות הגה רכות אינן מגדילות את הגל</li>
                </ul>
                <p>הפיזיקה של המיכלית המלאה בחלקה היא עניינם של המתכנן והנהג כאחד: היצרן מעלה את הסף באמצעות תכנון דלגקיר וחתך; הנהג אינו מתקרב לסף כלל באמצעות בחירת מהירות ותמרון. מחקרי מידול אקדמיים מאשרים אף הם שיש לטפל בשתי החזיתות הללו במשולב.</p>
