                <p>מכיוון שנפח הגז בלחץ משתנה באופן ניכר עם הטמפרטורה, המיכל לעולם אינו מתמלא לגמרי; בכל מילוי נשאר נפח הבטיחות שאליו יתרחב הנוזל המתחמם. שמירה על גוון בהיר של הגוף מפני קרינת השמש ומשטחים משקפים הם אמצעים פשוטים אך יעילים המונעים עלייה מיותרת בלחץ הפנימי. בעת ההעברה, בדיקת דליפות בחיבורים נעשית במשמעת מחמירה יותר מהבדיקה החזותית בדלק, באמצעות גלאי.</p>
                <p>לסיכום: תכנון מיכלית LPG אינו הוספת לחץ לרכב המוביל נוזל; זהו העברת הנדסת ציוד הלחץ אל השלדה.</p>
            ',
        ],

        'chemical-tanker-compatibility' => [
            'title'   => 'תאימות מוצרים ומניעת זיהום צולב במיכליות כימיות',
            'excerpt' => 'בהובלה כימית קיימות שתי שאלות תאימות נפרדות: האם המוצר תואם לחומר המיכל, והאם הוא תואם לשאריות המטען הקודם? אף אחת מהן אינה נסבלת להזנחה.',
            'content' => '
                <p>בתפעול מיכליות כימיות, הבטיחות נבנית על שני צירים. הראשון הוא תאימות חומרית: המוצר המובל חייב להיות ידידותי כימית לדופן המיכל, לאטם, לשסתום ולמשאבה. השני הוא תאימות מוצר-מוצר: המטען החדש אינו אמור להיכנס לתגובה מסוכנת עם שאריות המטען הקודם, ואינו אמור להתלכלך מבחינת איכות.</p>
                <h2>תאימות חומרית: מתחילה ברשימה</h2>
                <p>לכל מיכלית יש רשימת מוצרים המגדירה אילו חומרים היא רשאית להוביל, ורשימה זו אינה המלצה אלא גבול. פלדת אל-חלד מובילה מגוון רחב של כימיקלים, ואילו מוצרים אגרסיביים מסוימים דורשים מיכל מרופד גומי או פולימר; החוליה החלשה הנשכחת ביותר היא דווקא האטמים והצינורות. גם אם הגוף עומד בעומס, אטם מחומר לא נכון מתנפח, מתקשה ומתחיל לדלוף תוך ימים.</p>
                <h2>משמעת נגד זיהום צולב</h2>
                <ul>
                    <li>רישום היסטוריית המטענים: המוצרים האחרונים שהוביל המיכל מתועדים; בין זוגות מוצרים מסוימים נדרש מטען ביניים חובה או שטיפה מיוחדת</li>
                    <li>שטיפה מאושרת: בעת החלפת מוצר, הניקוי מתבצע בתחנה מוסמכת ובנוהל המתאים למוצר; תעודת השטיפה היא מסמך הסבב</li>
                    <li>ציד נפח מת: השאריות הנותרות בגוף המשאבה, בחללי השסתומים ובתחתית הצנרת הן מקור הזיהום הנפוץ ביותר</li>
                    <li>הקדשה למוצר יחיד: בכימיקלים המסוכנים ביותר, הפתרון הבטוח ביותר הוא הקדשת המיכל למוצר יחיד</li>
                </ul>
                <p>בצד היצרן, המאבק בזיהום הצולב מתחיל בתכנון: שיפוע המבטיח ניקוז מלא, פריסת שסתומים ללא נפח מת, ואיכות פני שטח פנימית הניתנת לניקוי. מיכל הניתן לניקוי בקלות הוא גם המיכל הבטוח יותר וגם זה המבצע יותר סבבים.</p>
