        'tanker-safety-culture' => [
            'title'   => 'לקחים מתאונות מיכליות: כיצד בונים תרבות בטיחות?',
            'excerpt' => 'דוחות התאונות הגדולות מספרים תמיד את אותה תבנית: לא טעות בודדת, אלא שרשרת של הזנחות קטנות. תרבות הבטיחות היא צורת הארגון השוברת את השרשרת בחוליה הראשונה.',
            'content' => '
                <p>חקירות אירועים חמורים בתפעול מיכליות דומות זו לזו באופן מפתיע: לעיתים רחוקות קיימת טעות בודדת וגדולה. לרוב נראית שרשרת של הזנחות קטנות; בדיקה שהוחמצה, אי-תקינות שהושתקה, צינור שחוק שלא הוחלף. תרבות הבטיחות היא המערכת ההופכת את שבירת השרשרת הזו בחוליה הראשונה למשימתו של כל אחד.</p>
