        'eu-co2-standards-trailers' => [
            'title'   => 'תקני CO₂ אירופיים מגיעים לרכב הכבד: המשמעות עבור יצרני נגררים',
            'excerpt' => 'היקף תקני פליטת ה-CO₂ לרכב כבד באיחוד האירופי מתרחב; הנגרר אינו עוד רכיב פסיבי במשוואת הדלק, אלא רכיב הנמדד ומתועד.',
            'content' => '
                <p>האיחוד האירופי מחמיר בהדרגה את תקני פליטת ה-CO₂ לרכב כבד כדי להפחית את הפליטות הנובעות מהובלה בכביש. מסגרת זו, שעניינה זמן רב היה רק יצרני התומכים והמשאיות, מתרחבת כעת לכלול גם את הנגררים: תרומתם של הנגררים והנתמכים לצריכת הדלק נמדדת, מסווגת ומתועדת.</p>
                <h2>מדוע הנגרר נכנס למשוואה?</h2>
                <p>חלק ניכר מהתנגדות האוויר של צירוף תומך-נגרר נובע מגוף הנגרר; המשקל העצמי והתנגדות הגלגול של הצמיגים משפיעים גם הם ישירות על הצריכה. גורמי הרגולציה הכירו במציאות זו וקיבלו שלא ניתן להגיע ליעדי הפליטה רק באמצעות שיפורים בצד המנוע: נגרר יעיל משמעו רכב יעיל.</p>
                <h2>תוצאות מוחשיות ליצרן</h2>
                <ul>
                    <li>ציוד אווירודינמי, הפחתת משקל וצמיגים בעלי התנגדות נמוכה הופכים לקלט סטנדרטי בתכנון</li>
                    <li>תיעוד ביצועי היעילות של המוצרים באמצעות סימולציה סטנדרטית מתווסף לתהליכי הייצור</li>
                    <li>קוני הצי דורשים בתדירות גוברת נתוני ביצועי CO₂ בהחלטות הרכש</li>
                    <li>עבור יצרנים המייצאים לשוק האירופי, ההתאמה הופכת לתנאי מוקדם לגישה לשוק</li>
                </ul>
                <p>שינוי זה אינו נטל עבור יצרן הנגררים, אלא תחום ליצירת הבדל. חבילות אווירודינמיות, הנדסת חומרים קלים ותכנון ממוקד יעילות הופכים, יחד עם הרגולציה, לטיעון מכירה מדיד; היצרן המוכן ייבדל מיריביו ככל שהתקנים יחמירו.</p>
                <h2>מקורות</h2>
                <ul>
                    <li>Van Raemdonck, G. M. R. &amp; Urila, I. (2019). A Study in Options to Improve Aerodynamic Profile of Heavy-Duty Vehicles in Europe. <em>Sustainability</em>, 11(19), 5519. DOI: 10.3390/su11195519</li>
                </ul>
            ',
        ],

