            'excerpt' => 'מחיר הרכישה הוא רק שער הכניסה לעלות האמיתית של הנגרר עבורכם; החישוב האמיתי הוא סכום כל החשבונות שהרכב כותב לאורך כל חייו.',
            'content' => '
