                    <li><strong>תחזוקה ותיקונים:</strong> תחזוקה מתוכננת, נגישות חלפים ועבודת כפיים</li>
                    <li><strong>עלות השבתה:</strong> ההכנסה החומקת בכל יום שהרכב אינו פועל</li>
                    <li><strong>ערך יד שנייה:</strong> ההון החוזר ברגע ההוצאה משימוש</li>
