            'content' => '
                <p>Platooning של משאיות הוא מצב שבו שני רכבים כבדים או יותר מתואמים אלקטרונית באמצעות תקשורת בין-רכבית, ונוסעים בשיירה במרווח נמוך משמעותית ממרחק המעקב הרגיל. הרכב המוביל מעביר לשיירה מיידית את החלטות ההאצה והבלימה; מכיוון שהרכבים שמאחור מגיבים מהר בהרבה מרפלקס אנושי, המרווח הקצר הופך לבטוח.</p>
                <h2>מהיכן מגיעה הכלכלה הדלקית?</h2>
                <p>במהירויות נסיעה בין-עירונית, חלק ניכר מהאנרגיה מוקדש להתגברות על התנגדות האוויר. ברכב הנוסע בשיירה, הרכב האחורי נע באזור הלחץ הנמוך שיוצר הרכב שלפניו, וההתנגדות שהוא פוגש קטנה במידה ניכרת; גם הרכב המוביל נהנה בחלקו מהתאוששות אזור הזרם שמאחוריו. ספרות האווירודינמיקה של רכב כבד מתייחסת ל-platooning כאל אפשרות תפעולית להפחתת התנגדות, המשלימה ציוד רכב כגון חצאיות צד וסידור אחורי.</p>
