                </ul>
                <p>צד הנגרר אינו שותף פסיבי במשוואה זו: מהירות התגובה של מערכת הבלמים, חלקות הציוד האווירודינמי ודיוק נתוני עומס הסרן משפיעים ישירות הן על בטיחות השיירה והן על רווחיה. ככל ש-platooning יתפשט, מושג "הנגרר המוכן לשיירה" ייכנס לקריטריוני הרכש.</p>
