            'excerpt' => 'המשתנה העיקרי הקובע את גודל הרווח בשיירה הוא המרחק בין הרכבים; אך המרווח הקצר ביותר אינו תמיד המרווח היעיל ביותר.',
            'content' => '
                <p>השאלה הנשאלת לרוב בדיוני platooning היא: כמה קרוב צריכים הרכבים להיות זה לזה? מבחינה אווירודינמית התשובה נראית פשוטה: ככל שהמרחק מתקצר, אזור הזרם שבו נע הרכב האחורי מתחזק, ורווח ההתנגדות גדל. בתפעול אמיתי, לעומת זאת, המשוואה מורכבת בהרבה יותר.</p>
                <h2>שני צדי המרחק</h2>
                <p>במרווחים קצרים מאוד, אוויר קירור המנוע של הרכב האחורי פוחת, שדה הראייה של החיישנים מצטמצם, ומרווח הביטחון בתרחישי בלימה נעשה דק יותר. ככל שהמרווח מתארך, סיכונים אלה נסוגים; אך גם החדירה של רכבים אחרים בין השיירה (cut-in) נעשית קלה יותר, וכל פיצול מאפס את הרווח עד להקמה מחדש של השיירה. לכן בפועל, היעד אינו מספר אידיאלי בודד, אלא רצועת מרחק דינמית המנוהלת בהתאם לכביש, לתנועה ולתנאי מזג האוויר.</p>
                <h2>משתנים נוספים המשפיעים על הרווח</h2>
                <ul>
                    <li>מהירות השיוט: מכיוון שהתנגדות האוויר גדלה בריבוע המהירות, הרווח משמעותי במהירות גבוהה</li>
                    <li>אורך השיירה: הרכבים באמצע נהנים מהחלק הגדול ביותר מהאפקט הדו-כיווני</li>
                    <li>גיאומטריית הרכב: צירופי ארגז, מיכלית ולואבד מייצרים פרופילי זרם שונים</li>
                    <li>רוח צולבת: מזיזה את אזור הזרם הצידה ומכרסמת ברווח</li>
                </ul>
                <p>הסיכום הכן הוא: הרווח מ-platooning אמיתי וניתן למדידה, אך אין לו מספר קטלוגי. הלקח שהספרות האווירודינמית מציעה עבור ציוד הרכב תקף גם כאן: ההחלטה חייבת להתבסס על נתונים שנאספו בתנאים הדומים למסלול ולפרופיל המהירות שלכם עצמכם.</p>
                <h2>מקורות</h2>
                <ul>
                    <li>Van Raemdonck, G. M. R. &amp; Urila, I. (2019). A Study in Options to Improve Aerodynamic Profile of Heavy-Duty Vehicles in Europe. <em>Sustainability</em>, 11(19), 5519. DOI: 10.3390/su11195519</li>
                </ul>
            ',
        ],

