                    <li>נתוני בלם, צמיג ומטען הניתנים למעקב מרחוק בקטע האוטונומי</li>
                    <li>תחנות בקרה לבדיקה וניקוי חיישנים בנקודות המעבר</li>
                    <li>תמיכת מרכז תפעול עם זרם נתוני מזג אוויר ודרך לאורך המסלול</li>
                </ul>
                <p>היישומים הראשונים מתחילים במסלולים קבועים, בתנאי מזג אוויר מוגבלים ובליווי נהג בטיחות; ככל שהמודל יבשיל, ההיקף יתרחב. מפעילים המתכננים את נגרריהם כך שיוכלו לייצר נתונים ולעבור חילופין, יהיו החוליה הראשונה שתתחבר לשרשרת זו.</p>
            ',
