        'autonomous-liability-insurance' => [
            'title'   => 'אחריות וביטוח ברכב כבד אוטונומי: מבט משפטי',
            'excerpt' => 'למי עוברת האחריות כאשר הנהג יוצא מהתמונה? השאלה הגדולה ביותר העומדת בפני ההובלה האוטונומית אינה טכנית, אלא משפטית ואקטוארית.',
            'content' => '
                <p>ככל שטכנולוגיית הרכב הכבד האוטונומי מבשילה, מרכז הכובד של הדיון נע מההנדסה אל המשפט. חוק התעבורה הקלאסי מבסס את האחריות במידה רבה על התנהגות הנהג; בתרחיש שבו אין נהג, או שהוא רק משגיח, יש להגדיר קרקע זו מחדש.</p>
