                <p>המגמה הכללית היא היסט מאחריות אשם לאחריות מוצר ומפעיל: תקלה במערכת האוטונומית עשויה להצביע על היצרן וספק התוכנה, כשל הנובע מהזנחת תחזוקה על מפעיל הצי, ובעיות הנובעות מהתשתית על מפעיל הדרך. מדינות שונות מעגנות חלוקה זו בחקיקה בקצבים שונים; בהובלה בין-לאומית, שונות זו היא שכבת סיכון נוספת שיש לנהל.</p>
                <h2>הערך העולה של הנתון</h2>
                <ul>
                    <li>מכשירי רישום אירועים המתעדים שנייה אחר שנייה את רגע התאונה, והופכים לראיה המרכזית בניתוח האשם</li>
                    <li>רישומי נתוני תחזוקה ובלמים של הנגרר הם ההוכחה לחובת הזהירות של המפעיל</li>
                    <li>תמחור הביטוח מתפתח מהיסטוריית הנהג לעבר איכות נתוני המערכת והצי</li>
