                <p>אבטחת מטען אינה רשימת ציוד, אלא עניין של חישוב והרגל. הנהג המיישם את הציוד הנכון בנקודה הנכונה, בזווית הנכונה ובמספר מספיק, מגן לא רק על המטען אלא גם על עצמו ועל התנועה.</p>
