        'ebs-diagnostics' => [
            'title'   => 'אבחון תקלות באמצעות נתוני מערכת בלמים אלקטרונית',
            'excerpt' => 'מערכת הבלמים של הנגרר המודרני היא גם מקור נתונים; שירות היודע לקרוא את זיכרון ה-EBS מוצא את התקלה ברישום, לא בניחוש.',
