                    <li><strong>ערכי חיישן עומס:</strong> עומס הסרן הנקרא מלחץ המתלים; הבסיס לחלוקת כוח הבלימה</li>
                    <li><strong>מוני קילומטראז׳ ושימוש:</strong> נתוני שימוש אמיתיים לתכנון תחזוקה</li>
                </ul>
