            'excerpt' => 'ככל שלהבי הטורבינה ומקטעי המגדל מתארכים, גם המוביל חייב להתארך יחד איתם; הלואבד הטלסקופי הפך לעמוד השדרה של לוגיסטיקת האנרגיה המתחדשת.',
