                <h2>ההיגיון של השילדה הטלסקופית</h2>
                <p>השילדה המתארכת פועלת באמצעות נעילה מדורגת של פרופילי קורה המשתלבים זה בזה: הפלטפורמה נפתחת בהתאם לאורך המטען; בחזרה ריקה היא מתקפלת ומתקרבת למידות הרכב הרגילות. אופי כפול זה הוא ליבת התפעול — האורך הדרוש מובטח בנסיעה עמוסה, בעוד שהחזרה הריקה נעשית בתנאי תנועה סטנדרטיים ובעלות נמוכה יותר. בדגמים המתארכים במספר מדרגות, ניהול הכבלים וקו הבלמים נפתר באמצעות מערכות גלגלת בתוך השילדה.</p>
                <h2>הדקויות של הובלת הלהבים</h2>
                <ul>
                    <li>הלהב יושב על משכבי מתאם ייעודיים; אין להטיל עומס נקודתי על המשטח המרוכב</li>
                    <li>רדיוס ההיטלטלות של המטען הארוך מחייב סקר מסלול במעברי סיבוב וצמתים</li>
                    <li>תנודת קצה הלהב מנוהלת בהתאם למגבלת המהירות ומצב הרוח</li>
                    <li>בשטח הררי נכנסות לפעולה גרסאות של מתאם הלהב המסוגלות להקצין את זווית הלהב</li>
                </ul>
                <p>בהערכת השקעה בלואבד מתארך, יש להתבונן לא רק באורך המרבי; אלא גם ביכולת התמרון במצב מקופל, בבטיחות הנעילה של מדרגות ההתארכות, ובשמירת איזון עומסי הסרן בכל מדרגה. לוח הזמנים של המעבר האנרגטי נמדד בטורבינות המוקמות בשטח; הרכבים המובילים טורבינות אלה לשטח פועלים בזכות פרטי הנדסה שקטים אלה.</p>
