        'reefer-panel-atp' => [
            'title'   => 'טכנולוגיית פאנלים ותעודת ATP במרכבים פריגורפיים',
            'excerpt' => 'לא משנה כמה חזקה יחידת הקירור, האלמנט השומר על הטמפרטורה הוא פאנל המרכב; תעודת ATP היא ההוכחה הבין-לאומית להגנה זו.',
            'content' => '
                <p>בהובלה פריגורפית, תשומת הלב מופנית לרוב ליחידת הקירור; אולם היחידה רק משיבה את החום שאבד. את האובדן עצמו קובע המרכב: איכות הבידוד של הפאנלים מגדירה הן את צריכת האנרגיה של הרכב והן את מגוון המוצרים שהוא יכול לשאת.</p>
                <h2>אנטומיית הפאנל הסנדוויצ׳י</h2>
                <p>המרכב הפריגורפי המודרני מורכב מפאנלים סנדוויצ׳יים שבין שני משטחי פנים מוזרם קצף פוליאוריתן בצפיפות גבוהה. המשטחים הם בדרך כלל פוליאסטר מחוזק או פח מצופה; העבודה האמיתית מתרחשת בליבת הקצף בעל התאים הסגורים. הפרטים הקובעים את איכות הפאנל אינם נראים לעין: מילוי אחיד של הקצף, רציפות במחברי הפאנלים, ותכנון חיבור שאינו יוצר גשר תרמי. הרצפה גם היא מובנית כך שלא תימעך תחת עומס ותעמוד בתנועת מלגזה.</p>
